"""Finish ILD with twelve original sarcoidosis questions."""
from create_autoimmune_ild import rows,q
from qbank_authoring import ref,finalize
SA=ref('ATS: Diagnosis and Detection of Sarcoidosis, 2020','https://pmc.ncbi.nlm.nih.gov/articles/PMC7159433/')
ST=ref('ERS: Treatment of Sarcoidosis, 2021','https://publications.ersnet.org/lookup/pmid/34140301')
PM=ref('PREDMETH: Initial Prednisone versus Methotrexate in Pulmonary Sarcoidosis, 2025','https://www.nejm.org/doi/full/10.1056/NEJMoa2501443')
CS=ref('AHA: Diagnosis and Management of Cardiac Sarcoidosis, 2024','https://www.ahajournals.org/doi/pdf/10.1161/CIR.0000000000001240')
q('A young adult has bilateral hilar adenopathy, tender shin nodules and acute bilateral ankle periarthritis. Which syndrome best integrates these findings?', 'Lofgren syndrome',[
 ('Heerfordt syndrome','This centers on uveitis, parotid enlargement and facial palsy, rather than the ankle/erythema nodosum triad.'),('Blau syndrome','Early childhood granulomatous dermatitis, arthritis and uveitis suggest this inherited condition.'),('Granulomatosis with polyangiitis','Destructive ENT disease, nodules and glomerulonephritis are more characteristic.')],
 'Recognize acute sarcoidosis as a clinical constellation', '**The combination strongly supports acute sarcoidosis.**',['Erythema nodosum is a reactive panniculitis, not the preferred biopsy site for sarcoidal granulomas.','Ankle swelling may reflect periarticular inflammation.'], '**A highly characteristic presentation can support diagnosis without routine tissue sampling.**',['Assess alternative diagnoses and arrange follow-up.','Atypical features or an uncertain course change the need for biopsy.'],[['Lofgren','Hilar nodes, erythema nodosum, ankle inflammation'],['Heerfordt','Uveitis, parotid disease, facial palsy'],['Biopsy decision','Depends on diagnostic confidence']],[SA],style='clinical_scenario')
q('Uveitis, parotid enlargement, fever and a peripheral facial palsy occur together. Which sarcoidosis-associated syndrome is most likely?', 'Heerfordt syndrome',[
 ('Lofgren syndrome','The typical triad is hilar adenopathy, erythema nodosum and ankle inflammation.'),('Melkersson-Rosenthal syndrome','Recurrent facial edema, facial palsy and a fissured tongue define a different constellation.'),('Vogt-Koyanagi-Harada disease','Uveitis with auditory, meningeal and integumentary findings is a competing pattern, but parotid enlargement with facial palsy favors Heerfordt.')],
 'Parotid and ocular disease can identify multisystem sarcoidosis', '**Heerfordt syndrome is also called uveoparotid fever.**',['Facial nerve dysfunction may be unilateral or bilateral.','Incomplete presentations occur.'], '**Protect vision and assess neurological involvement promptly.**',['Ocular symptoms need ophthalmological assessment.','Evaluate mimics before attributing every finding to sarcoidosis.'],[['Eye','Uveitis'],['Salivary gland','Parotid enlargement'],['Nerve','Facial palsy']],[SA],style='clinical_scenario')
q('In the conventional chest-radiograph staging of pulmonary sarcoidosis, bilateral hilar adenopathy together with parenchymal infiltrates is classified as which stage?', 'Stage II',[
 ('Stage I','Hilar adenopathy without parenchymal infiltrates defines stage I.'),('Stage III','Parenchymal infiltrates without hilar adenopathy define stage III.'),('Stage IV','Established pulmonary fibrosis defines stage IV.')],
 'Radiographic stage describes a pattern, not a mandatory sequence', '**Stage II contains both nodal and parenchymal abnormalities.**',['Patients need not pass through all stages in order.','CT can characterize disease beyond the radiographic classification.'], '**Base treatment on organ risk, impairment and symptoms.**',['A stage number alone does not mandate a drug regimen.','Follow physiology and the clinical trajectory.'],[['I','Hilar adenopathy alone'],['II','Nodes plus infiltrates'],['III / IV','Infiltrates without nodes / fibrosis']],[SA,ST])
q('Sarcoidosis is suspected in a patient with mediastinal and hilar adenopathy. Tissue confirmation is required, and there is no accessible peripheral lesion. Which initial sampling approach is preferred?', 'EBUS-guided lymph node sampling',[
 ('Cervical mediastinoscopy','It can provide tissue but is more invasive and generally follows a less invasive nodal approach when appropriate.'),('Surgical lung biopsy','This is unnecessarily invasive as the initial approach to accessible thoracic adenopathy.'),('Bronchoalveolar lavage CD4/CD8 ratio alone','BAL findings may support a diagnosis but do not provide the needed histological confirmation.')],
 'Choose the least invasive informative tissue target', '**EBUS allows targeted intrathoracic nodal sampling.**',['The specimen must be interpreted with exposure and infection history.','A nondiagnostic result may require an alternative approach.'], '**Plan microbiology and pathology together.**',['Granulomas have several causes.','Accessible skin or peripheral nodes may offer an easier target in other patients.'],[['Accessible peripheral lesion','Consider targeted biopsy'],['Thoracic nodes','EBUS first when tissue is needed'],['Persistent uncertainty','Further sampling as indicated']],[SA],style='clinical_scenario')
q('A lymph node biopsy shows nonnecrotizing granulomas in a patient with thoracic adenopathy. Which next interpretation is most appropriate?', 'The finding supports sarcoidosis only after clinical correlation and exclusion of relevant alternative granulomatous causes',[
 ('The histology alone confirms sarcoidosis','No single granuloma pattern is pathognomonic.'),('The absence of necrosis excludes tuberculosis','TB can produce nonnecrotizing granulomas; microbiological evaluation depends on context.'),('The result establishes chronic beryllium disease','Exposure and beryllium-specific immune evidence are needed for that diagnosis.')],
 'A granuloma is a reaction pattern', '**Sarcoidosis requires a compatible syndrome and reasonable exclusion of mimics.**',['Relevant infections include mycobacteria and fungi.','Occupational exposure and drug reactions may alter the differential.'], '**Investigate before immunosuppression when infection is plausible.**',['Select stains, cultures and molecular tests according to risk.','A negative single test may not settle a high-probability alternative.'],[['Histology','Supportive pattern'],['Context','Exposure, distribution and manifestations'],['Exclusion','Targeted investigation of mimics']],[SA],style='clinical_scenario')
q('What is the most accurate role of serum angiotensin-converting enzyme in suspected sarcoidosis?', 'A nonspecific adjunct that cannot independently confirm or exclude the diagnosis',[
 ('A normal result rules out active sarcoidosis','Sensitivity is inadequate for a rule-out test.'),('An elevated result distinguishes sarcoidosis from all infections','Other granulomatous and nongranulomatous disorders can elevate ACE.'),('Its concentration alone determines the need for systemic treatment','Treatment depends on organ risk and clinical impact rather than an isolated marker.')],
 'Do not let a biomarker replace diagnostic reasoning', '**ACE may be supportive but lacks decisive specificity and sensitivity.**',['Assay and patient factors affect interpretation.','Medication, including ACE inhibition, can complicate assessment.'], '**Use longitudinal organ assessment to judge disease impact.**',['Symptoms, physiology and imaging provide complementary information.','A laboratory trend alone should not trigger escalation.'],[['High ACE','Supportive at most'],['Normal ACE','Does not exclude disease'],['Treatment decision','Organ risk and clinical impairment']],[SA,ST])
q('A patient has newly diagnosed stage I thoracic sarcoidosis, normal lung function, minimal symptoms and no organ-threatening involvement. Which initial strategy is most appropriate?', 'Observation with planned clinical and organ assessment',[
 ('Begin high-dose prednisone solely because hilar nodes are enlarged','An imaging finding alone does not establish a treatment indication.'),('Begin infliximab as routine initial treatment','Biologic treatment is generally reserved for selected refractory disease.'),('Discharge permanently without follow-up','Extrapulmonary manifestations or progression can emerge.')],
 'Treat risk and burden rather than every radiographic abnormality', '**Observation is reasonable when disease is mild and low risk.**',['Spontaneous improvement can occur.','Avoid exposing a minimally affected patient to unnecessary treatment toxicity.'], '**Reassess for functional decline, troublesome symptoms or organ threat.**',['Cardiac, neurological and sight-threatening disease require a different urgency.','Discuss symptoms and quality of life rather than relying only on radiographic stage.'],[['Mild low-risk disease','Observation may be appropriate'],['Threatened organ function','Active treatment assessment'],['Follow-up','Clinical and organ-based']],[ST,SA],style='clinical_scenario')
q('Which conclusion is supported by the 2025 PREDMETH trial in treatment-naive pulmonary sarcoidosis?', 'Initial methotrexate was noninferior to prednisone for change in percent-predicted FVC at 24 weeks',[
 ('Methotrexate was proven superior for long-term mortality','The trial did not establish this endpoint.'),('Prednisone and methotrexate have identical adverse-effect profiles','Their toxicities and monitoring requirements differ.'),('Methotrexate must replace glucocorticoids in every organ-threatening presentation','The pulmonary trial does not establish that universal strategy.')],
 'Match the trial conclusion to its population and endpoint', '**PREDMETH supports methotrexate as an initial-treatment alternative in selected pulmonary disease.**',['The endpoint was FVC change at 24 weeks.','This does not prove equivalence for every sarcoidosis manifestation.'], '**Choose therapy jointly according to urgency, comorbidity and toxicity.**',['Methotrexate requires folate and blood-count, liver and renal monitoring.','Pregnancy planning and contraindications must be addressed; glucocorticoids have different risks and speed of action.'],[['Evidence','Pulmonary FVC at 24 weeks'],['Choice','Individualized benefit and harm'],['Generalization','Not all organ-threatening disease']],[PM,ST])
q('A patient with extracardiac sarcoidosis develops unexplained syncope and high-grade AV block despite preserved left ventricular ejection fraction. What is the priority?', 'Urgent evaluation for cardiac sarcoidosis and dangerous conduction disease',[
 ('Reassurance because preserved EF excludes cardiac involvement','Conduction-system disease can precede systolic dysfunction.'),('Attribute the episode to vasovagal syncope without rhythm assessment','High-grade AV block is a high-risk explanation.'),('Wait for the next routine ACE measurement before cardiac work-up','A serum marker cannot assess immediate arrhythmic risk.')],
 'Cardiac sarcoidosis can present electrically before pump failure', '**AV block, ventricular arrhythmia or unexplained syncope warrants urgent assessment.**',['Provide immediate rhythm stabilization when needed.','CMR and appropriately prepared FDG-PET assess complementary aspects of myocardial disease.'], '**Separate inflammation assessment from sudden-death prevention.**',['Immunosuppression does not substitute for indicated pacing or defibrillator evaluation.','A negative unguided myocardial biopsy has limited exclusion value.'],[['Conduction disease','May occur with preserved EF'],['CMR','Scar and tissue characterization'],['FDG-PET','Inflammatory activity with appropriate preparation']],[CS],style='clinical_scenario')
q('A patient with pulmonary sarcoidosis develops polyuria with dilute urine and an enhancing hypothalamic-pituitary lesion. Which mechanism best explains the water-balance disturbance?', 'Hypothalamic-pituitary involvement causing arginine vasopressin deficiency',[
 ('SIADH from excess vasopressin','SIADH produces impaired water excretion rather than a primary dilute-water diuresis.'),('Primary adrenal insufficiency as the direct cause of dilute polyuria','It can cause systemic illness and hyponatremia but does not best explain the lesion and water diuresis.'),('Renal vasopressin resistance established by the MRI alone','MRI localizes a central process; renal resistance requires a different physiological assessment.')],
 'Neurosarcoidosis can affect endocrine pathways', '**Inflammation can disrupt AVP production or release.**',['Assess serum sodium, serum and urine osmolality and fluid balance.','Other pituitary axes may also be affected.'], '**Establish attribution rather than assuming every lesion is sarcoidosis.**',['MRI and CSF findings are supportive but not individually definitive.','Exclude infection and malignancy and seek safer extraneural tissue when appropriate.'],[['Central AVP deficiency','Hypothalamic-pituitary pathway'],['Nephrogenic resistance','Renal response abnormality'],['SIADH','Water retention rather than dilute diuresis']],[SA,ST],style='clinical_scenario')
q('Sarcoidosis is associated with hypercalcemia, suppressed PTH and an inappropriately high 1,25-dihydroxyvitamin D concentration. What is the principal mechanism?', 'Extrarenal calcitriol production by activated granuloma macrophages',[
 ('Autonomous PTH secretion from a parathyroid adenoma','PTH would be inappropriately nonsuppressed in primary hyperparathyroidism.'),('PTH-related peptide secretion as the usual sarcoidosis mechanism','This is a competing mechanism in malignancy rather than the characteristic granulomatous pathway.'),('Failure of intestinal calcium absorption','Calcitriol increases intestinal absorption rather than reducing it.')],
 'Granulomatous inflammation can uncouple calcitriol production from normal regulation', '**Activated macrophage 1-alpha-hydroxylase increases active vitamin D.**',['Increased intestinal calcium uptake can cause hypercalcemia and hypercalciuria.','Renal stones and renal injury may follow.'], '**Review calcium and vitamin D exposure and treat severity appropriately.**',['Do not reflexively prescribe high-dose vitamin D on a low 25-hydroxyvitamin D value without assessing calcium metabolism.','Glucocorticoids can suppress granulomatous calcitriol production when treatment is indicated.'],[['PTH','Usually suppressed'],['Calcitriol','Inappropriately elevated'],['Complications','Hypercalciuria, stones and kidney injury']],[SA,ST],style='clinical_scenario')
q('Which baseline evaluation is appropriate in a patient with newly established sarcoidosis who reports no eye or cardiac symptoms?', 'Baseline eye examination, ECG and serum calcium with assessment of renal and other organ involvement',[
 ('Routine endomyocardial biopsy in every patient','Its invasiveness and limited sampling sensitivity make this unsuitable as universal screening.'),('ACE alone followed by organ testing only if elevated','ACE cannot reliably select patients for extrapulmonary assessment.'),('Universal cardiac FDG-PET without initial clinical evaluation','Advanced testing is guided by suspicion rather than required for every asymptomatic patient.')],
 'Silent organ disease is clinically relevant', '**Baseline screening combines history, examination and selected organ tests.**',['ATS guidance includes an eye examination, ECG and serum calcium.','Renal function, blood count and liver assessment also help identify involvement.'], '**Escalate testing when symptoms or abnormalities create suspicion.**',['Palpitations, syncope or conduction abnormalities require targeted cardiac evaluation.','Follow-up should track organ function and symptoms rather than ACE alone.'],[['Baseline','Clinical review and selected screening'],['Abnormal findings','Targeted investigation'],['Monitoring','Organ-based rather than marker-only']],[SA,CS])

if __name__=='__main__':finalize('Respiratory system',3,'Interstitial Lung Disease','resp-ild',rows,40)
